```cpp
__device__ __forceinline__ int64_t HtoBE64(int64_t val) {
    int32_t lo, hi;
    asm("mov.b64 {%0, %1}, %2;" : "=r"(lo), "=r"(hi) : "l"(val));

 // use prmt rowbytescolumn(byte permutation)
    int32_t rlo, rhi;
    asm("prmt.b32 %0, %1, %2, 0x0123;"
        : "=r"(rhi) : "r"(lo), "r"(0));
    asm("prmt.b32 %0, %1, %2, 0x0123;"
        : "=r"(rlo) : "r"(hi), "r"(0));

    int64_t result;
    asm("mov.b64 %0, {%1, %2};" : "=l"(result) : "r"(rlo), "r"(rhi));
    return result;
}
